import { RTKWrapper } from '06_shared/components/RTKWrapper/RTKWrapper';
import { userApi, useGetMeQuery } from '05_entities/user';
import { UserContext } from '06_shared/contexts/UserContext';
import { LS_ACCESS_TOKEN } from '06_shared/constants/localStorage';
import { useCallback, useContext, useEffect, useState } from 'react';
const UserLoader = () => {
    // Без access-токена сесії немає: auth/me гостю віддав би 403, а baseQuery ще
    // й спробував би оновити токен — два марні запити на старті. Дані читаємо
    // зі стану кешу, а не з самого запиту: логін кладе токен і сам запитує
    // getMe, тож користувач зʼявиться й тоді, коли на старті запит не йшов.
    const [hasToken] = useState(() => localStorage.getItem(LS_ACCESS_TOKEN) !== null);
    useGetMeQuery(undefined, { skip: !hasToken });
    const { data, isSuccess, error } = userApi.endpoints.getMe.useQueryState();
    const { setUser, setIsInit } = useContext(UserContext);
    const onSuccess = useCallback(() => {
        if (!data?.result)
            return;
        setIsInit(false);
        setUser(data?.result);
    }, [data?.result, setIsInit, setUser]);
    const onError = useCallback(() => {
        setIsInit(false);
    }, [setIsInit]);
    useEffect(() => {
        isSuccess && onSuccess();
    }, [isSuccess, onSuccess]);
    useEffect(() => {
        (error || !hasToken) && onError();
    }, [error, hasToken, onError]);
    return null;
};
export default RTKWrapper(UserLoader, [userApi], {}, false, null);
